using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class DestructionAuthoringOperations
{
    public bool guidance(RefCounted controller,string owner,Settings fragment,Settings values,double time,double h)
    {
        var rules=Get(values,"destruction_fragments",new Settings()).AsGodotDictionary();var rule=Get(rules,fragment_key(owner,fragment["id"].AsString()),new Settings()).AsGodotDictionary();if(rule.Count==0||!Get(rule,"enabled",true).AsBool())return false;var actor=controller.Get("prototypes").AsGodotDictionary()[owner].AsGodotDictionary()["actor"].As<Resource>();double local=controller.Call("_local",actor,time).AsDouble();var pose=fragment["pose"].AsTransform3D();if(!Get(fragment,"directed_initialized",false).AsBool()){fragment["v"]=fragment["v"].AsVector3()+Get(rule,"velocity",Vector3.Zero).AsVector3();fragment["w"]=fragment["w"].AsVector3()+Get(rule,"angular_velocity",Vector3.Zero).AsVector3()*(Mathf.Pi/180);fragment["mass"]=Math.Max(.001,fragment["mass"].AsDouble()*Math.Clamp(Get(rule,"mass_scale",1).AsDouble(),.01,100));fragment["directed_initialized"]=true;fragment["pin_pose"]=pose;}if(local>=Get(rule,"impulse_time",0).AsDouble()&&!Get(fragment,"directed_impulse",false).AsBool()){fragment["v"]=fragment["v"].AsVector3()+Get(rule,"impulse",Vector3.Zero).AsVector3()/(float)fragment["mass"].AsDouble();fragment["directed_impulse"]=true;fragment["sleep"]=0.0;}double pin=Get(rule,"pin_until",-1).AsDouble();if(pin>=0&&local<pin){fragment["pose"]=fragment["pin_pose"];fragment["v"]=Vector3.Zero;fragment["w"]=Vector3.Zero;fragment["responds"]=false;return true;}double end=Get(rule,"to",-1).AsDouble();int mode=local>=Get(rule,"from",0).AsDouble()&&(end<0||local<end)?Get(rule,"mode",0).AsInt32():0;if(mode==2){var target=Get(rule,"target",pose.Origin).AsVector3();fragment["v"]=(target-pose.Origin)/(float)Math.Max(.00001,h);pose.Origin=target;fragment["pose"]=pose;fragment["directed_animated"]=true;fragment["responds"]=false;return true;}fragment["directed_animated"]=false;if(mode==1){var acceleration=(Get(rule,"target",pose.Origin).AsVector3()-pose.Origin)*(float)Math.Max(0,Get(rule,"strength",25).AsDouble())-fragment["v"].AsVector3()*(float)Math.Max(0,Get(rule,"damping",8).AsDouble());fragment["v"]=fragment["v"].AsVector3()+acceleration.LimitLength(500)*(float)h;fragment["sleep"]=0.0;}return false;
    }
    public void apply_overrides(RefCounted controller,double time){var states=controller.Get("display_states").AsGodotDictionary();var prototypes=controller.Get("prototypes").AsGodotDictionary();foreach(var owner in states.Keys){var actor=prototypes[owner].AsGodotDictionary()["actor"].As<Resource>();var values=_animation.sampled_values(actor,controller.Call("_local",actor,time).AsDouble());var corrections=Get(values,"destruction_overrides",new Settings()).AsGodotDictionary();var state=states[owner].AsGodotDictionary();foreach(var value in Get(state,"destruction_fragments",new GArray()).AsGodotArray()){var fragment=value.AsGodotDictionary();var rule=Get(corrections,fragment_key(owner.AsString(),fragment["id"].AsString()),new Settings()).AsGodotDictionary();if(rule.Count==0||!Get(rule,"enabled",true).AsBool())continue;double timing=Get(rule,"time_offset",0).AsDouble(),speed=Get(rule,"time_scale",1).AsDouble(),freeze=Get(rule,"freeze_time",-1).AsDouble();if(!Mathf.IsZeroApprox(timing)||!Mathf.IsEqualApprox(speed,1)||freeze>=0){var config=_physics.sample(actor,controller.Call("_local",actor,time).AsDouble());var sample=controller.Call("_baked",config["bake"],freeze>=0?freeze:time*speed+timing).AsGodotDictionary();foreach(var item in Get(sample,"destruction_fragments",new GArray()).AsGodotArray()){var candidate=item.AsGodotDictionary();if(candidate["id"].AsString()!=fragment["id"].AsString())continue;fragment["pose"]=candidate["pose"];break;}}var pose=fragment["pose"].AsTransform3D();pose.Origin+=Get(rule,"offset",Vector3.Zero).AsVector3();pose.Basis=Basis.FromEuler(Get(rule,"rotation",Vector3.Zero).AsVector3()*(Mathf.Pi/180))*pose.Basis;fragment["pose"]=pose;}double shift=Get(values,"destruction_vfx_offset",0).AsDouble();if(!Mathf.IsZeroApprox(shift))foreach(var item in Get(state,"destruction_events",new GArray()).AsGodotArray()){var entry=item.AsGodotDictionary();entry["time"]=entry["time"].AsDouble()+shift;}}}
}
